<?php

namespace App\Actions\Finance;

use App\Enums\EntryStatus as EntryStatusEnum;
use App\Models\FinancialEntry;
use Illuminate\Validation\ValidationException;

/**
 * Edit a manual entry (US-10.1) with the same rules as the creation. Entries
 * generated by payments are read-only, even for the admin: they only change
 * through the payment refund.
 */
class UpdateFinancialEntry
{
    /**
     * @param  array{entry_type?: mixed, financial_category_id?: mixed, description?: mixed, amount?: mixed, due_date?: mixed, supplier_or_payer?: mixed, notes?: mixed, is_paid?: mixed, paid_at?: mixed, payment_method?: mixed}  $input  Same format as CreateFinancialEntry.
     *
     * @throws ValidationException
     */
    public function handle(FinancialEntry $entry, array $input): FinancialEntry
    {
        if ($entry->isAutomatic()) {
            throw ValidationException::withMessages(['entry' => 'Lançamento automático de mensalidade não pode ser alterado; use o estorno do pagamento.']);
        }

        if ($entry->entry_status_id === EntryStatusEnum::Cancelled->id()) {
            throw ValidationException::withMessages(['entry' => 'Lançamento cancelado não pode ser alterado.']);
        }

        $entry->update(CreateFinancialEntry::validate($input, $entry));

        return $entry;
    }
}
